<script setup lang="ts">
import {ref,computed} from 'vue'
import {onShow,onHide} from '@dcloudio/uni-app'
import {request,navigate,token,type Row} from '../../api/platform'
import {abandonLogin as cancelLogin} from '../../features/auth'
import LoginSheet from '../../components/LoginSheet.vue'
import PageState from '../../components/PageState.vue'
const settings=ref<Row|null>(null),error=ref(''),busy=ref(false),loading=ref(false),notice=ref(''),linking=ref(false),requesting=ref(false),showQr=ref(false)
const wecomState=computed(()=>settings.value?String(settings.value.wecomState||'NONE'):'NONE')
async function load(){if(!token()){settings.value=null;return}loading.value=true;error.value='';try{settings.value=await request('GET','/api/v1/me/reminders/settings')}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function save(){if(!settings.value||busy.value)return;busy.value=true;error.value='';notice.value='';try{settings.value=await request('PUT','/api/v1/me/reminders/settings',{enabled:settings.value.enabled,slot:settings.value.slot,expectedVersion:settings.value.lockVersion});notice.value='提醒设置已保存'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function linkWecom(){if(!settings.value||linking.value)return;linking.value=true;error.value='';notice.value='';try{settings.value=await request('POST','/api/v1/me/reminders/wecom-link');notice.value='已完成添加'}catch(e){error.value=(e as Error).message}finally{linking.value=false}}
async function requestWecom(){if(!settings.value||requesting.value)return;requesting.value=true;error.value='';notice.value='';try{settings.value=await request('POST','/api/v1/me/reminders/wecom-request');notice.value='已添加企业微信，请点“我已完成添加”确认'}catch(e){error.value=(e as Error).message}finally{requesting.value=false}}
function confirmQr(){showQr.value=false;requestWecom()}
function cancel(){uni.navigateBack({fail:()=>navigate('notifications')})}
onShow(load);onHide(cancelLogin)
</script><template><view class="page"><view class="hero"><text class="title">强提醒设置</text><text class="subtitle">一个账号设置一个日常处理时段，全部日常规则共用。</text></view><PageState :busy="loading" :error="error" @retry="load"/><text v-if="notice" role="status" class="success">{{ notice }}</text><template v-if="settings"><view class="card"><view class="row"><text class="card-title">接收更新提醒</text><switch :checked="settings.enabled" :disabled="busy||wecomState!=='BOUND'" color="#50a770" @change="settings.enabled=!!($event as any).detail.value"/></view><text v-if="wecomState!=='BOUND'" class="muted">添加企业微信并完成绑定后，才能设置提醒开关与时段。</text><text class="field-label">日常提醒时段 · {{ settings.timezone }}</text><view class="actions"><button role="button" v-for="slot in settings.slots" :key="slot" :disabled="busy||wecomState!=='BOUND'" :class="settings.slot===slot?'':'quiet'" @click="settings.slot=slot">{{ slot }}</button></view><text class="muted">系统整理未读更新并创建企微任务，由工作人员在企微发送；所选时间是处理时段，不保证精确到达。关闭后暂停尚未发送的任务，已提交的平台任务可能仍被执行。</text></view><view class="card"><text class="card-title">企业微信联系关系</text><text class="badge">{{ wecomState==='BOUND'?'已记录联系关系':wecomState==='CONTACTED'?'已添加企微，待确认':'尚未添加企业微信' }}</text><text v-if="settings.localSimulation" class="muted">当前是本地模拟验收，不会向真实用户发送消息。</text><template v-else><text class="muted">添加企微客服后由平台回调自动核验；回调未及时到达时可点下方按钮确认。</text><!-- #ifdef MP-WEIXIN --><contact-cell plugid="951a513eec0d4e5ccd5a5e0a4c69620f"/><!-- #endif --></template><view class="actions"><button v-if="wecomState==='NONE'" role="button" @click="showQr=true">添加企业微信</button><button v-if="wecomState!=='BOUND'" role="button" :disabled="wecomState!=='CONTACTED'||linking" @click="linkWecom">我已完成添加</button></view><text v-if="wecomState==='BOUND'" class="success">已完成添加</text></view><view class="bottom-actions"><button role="button" class="quiet" :disabled="busy" @click="cancel">取消</button><button role="button" :disabled="busy" @click="save">保存设置</button></view></template><button role="button" v-else-if="!loading&&!error" @click="navigate('login')">登录后设置</button><LoginSheet/><view v-if="showQr" class="sheet-mask" @click="showQr=false"><view class="qr-sheet" @click.stop><view class="qr-head"><text class="card-title">添加企业微信</text><text class="qr-close" @click="showQr=false">×</text></view><text class="muted">用微信扫一扫，添加「云迹」企业微信</text><view class="qr-box"><image src="/static/wecom-contact-qr.jpg" mode="aspectFit" style="width:100%;height:100%"/></view><text class="small muted">添加后关闭本窗口，回到页面点「我已完成添加」</text><button role="button" :disabled="requesting" @click="confirmQr">我已扫码，下一步</button></view></view></view></template>
